<script setup lang="ts">
/**
 * ConnectorLogo — renders the native brand SVG mark for a connection type.
 *
 * Usage:
 *   <ConnectorLogo type="supabase" :size="32" class="text-accent" />
 *
 * All logos are mono-colour, inheriting `currentColor` so they can be
 * tinted via Tailwind text-color utilities or CSS color.
 *
 * Brand SVG paths sourced from Simple Icons (simpleicons.org).
 * Webhook and Syslog are custom icons (no official brand mark).
 */

withDefaults(defineProps<{
  /** The connector type key (matches flows.ts connectorType) */
  type: string
  /** Icon size in pixels (applied to both width and height) */
  size?: number
}>(), {
  size: 32,
})
</script>

